page.css:
@import url("https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700;800&family=Inter:wght@400;500;600;700&display=swap");

/* ===== base styles carried over from the site stylesheet ===== */
ul, ol{list-style:revert;margin:revert;padding:revert}
li{list-style:revert}
img, svg, video{max-width:revert;height:revert;display:revert;vertical-align:revert}
button, input, select, textarea{font:revert;color:revert;background:revert;border:revert;margin:revert;padding:revert;text-align:revert;line-height:revert}
table{border-collapse:revert;text-indent:revert}
blockquote, figure, fieldset{margin:revert;padding:revert}
h1, h2, h3, h4, h5, h6{font-size:revert;font-weight:revert;margin:revert;line-height:revert}
p{margin:revert}
a{color:revert;text-decoration:revert}
hr{border:revert;height:revert;color:revert}

*{box-sizing:border-box}
:root{/* static accents — same in both themes. Main = yellow; blue = the one 'touch' accent */
  --amber:#f7a80a;--amber-l:#ffc247;--gold:#ffd874;--amber-d:#c47a08;
  --cyan:#f7a80a;--cyan-d:#c47a08;--violet:#f7a80a;--violet-d:#c47a08;
  --blue:#3b82f6;--blue-l:#7ab0ff;--pink:#f7a80a;--green:#34e0a1;
  --grad:linear-gradient(120deg,#ffd874,#f7a80a);
  --grad-b:linear-gradient(120deg,#7ab0ff,#3b82f6);
  --gcyan:rgba(247,168,10,.55);--gviolet:rgba(247,168,10,.42);
  --gut:clamp(18px,5vw,44px);
  --fdisp:'Sora',system-ui,sans-serif;--fbody:'Inter',system-ui,sans-serif;
  --r:18px;}
/* ---- dark theme (default) — swappable tokens live on .site ---- */
:root{--bg:#07080f;--bg2:#0b0d16;--bg3:#0e1018;
  --ink:#f4f6fb;--ink2:#c9cfdd;--mut:#8b93a8;
  --line:rgba(255,255,255,.10);--line2:rgba(255,255,255,.18);
  --glass:rgba(255,255,255,.045);--glass2:rgba(255,255,255,.08);
  --base:#0a0c15;--cream:#0c0e18;
  --hdrbg:#0a0d16;--hdrtext:#dbe2f5;--capbg:#0c0f1c;--menubg:#0d111d;
  --utilbg:#05060f;--utiltext:#9aa3c0;
  --shadow:0 24px 60px -28px rgba(0,0,0,.8);
  --glow:0 0 0 1px rgba(247,168,10,.3),0 18px 50px -18px rgba(247,168,10,.3),0 10px 40px -14px rgba(0,0,0,.5);
  --page-grad:radial-gradient(900px 600px at 12% -5%,rgba(247,168,10,.10),transparent 60%),radial-gradient(900px 620px at 92% 4%,rgba(59,130,246,.10),transparent 60%)}
/* ---- WHITE rows — light section to break up the dark ---- */
.rowlight{background:#f4f6fc;
  --ink:#0e1424;--ink2:#42506a;--mut:#697390;
  --line:rgba(14,20,36,.10);--line2:rgba(14,20,36,.16);
  --glass:#ffffff;--glass2:#eef2f9;
  --base:#f4f6fc;--cream:#f4f6fc;
  --glow:0 0 0 1px rgba(247,168,10,.35),0 18px 40px -20px rgba(247,168,10,.3),0 10px 30px -16px rgba(20,30,60,.15);
  color:var(--ink)}
.rowlight .vc, .rowlight .svc, .rowlight .rev, .rowlight .plan, .rowlight .ind, .rowlight .pstep{box-shadow:0 14px 36px -22px rgba(20,30,60,.3)}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);background-image:var(--page-grad);background-attachment:fixed;
  color:var(--ink);min-height:100vh;font-family:var(--fbody);
  font-size:16.5px;line-height:1.62;-webkit-font-smoothing:antialiased;overflow-x:hidden}
img{max-width:100%;display:block}
svg{width:18px;height:18px;flex-shrink:0}
a{color:inherit;text-decoration:none}
h1, h2, h3, h4{font-family:var(--fdisp);line-height:1.06;margin:0;letter-spacing:-.02em;font-weight:800}
p{margin:0 0 1em}
.wrap{max-width:1240px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.eyebrow{font-family:var(--fdisp);font-weight:700;font-size:.78rem;letter-spacing:.18em;
  text-transform:uppercase;color:var(--cyan)}
.k-amber{background:linear-gradient(100deg,#ffd874,#ffb23a 50%,#f7a80a);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 16px rgba(247,168,10,.35))}
.btn{display:inline-flex;align-items:center;gap:.5em;font-family:var(--fdisp);font-weight:700;
  font-size:.98rem;padding:.85em 1.5em;border-radius:999px;border:0;cursor:pointer;
  transition:transform .18s,box-shadow .18s,background .18s,border-color .18s;white-space:nowrap;position:relative}
.btn svg{width:18px;height:18px}
.btn-amber{background:linear-gradient(135deg,#ffc247,#f7a80a);color:#231704;
  box-shadow:0 0 26px -4px rgba(247,168,10,.6),0 0 46px -12px rgba(247,168,10,.45)}
.btn-amber:hover{transform:translateY(-3px);box-shadow:0 0 36px -2px rgba(247,168,10,.8),0 0 60px -10px rgba(247,168,10,.5)}
.btn-ghost{background:var(--glass);color:#fff;border:1px solid var(--line2);backdrop-filter:blur(8px)}
.btn-ghost:hover{border-color:var(--cyan);transform:translateY(-3px);box-shadow:0 0 24px -6px var(--gcyan)}
.btn-lg{padding:1.05em 1.9em;font-size:1.05rem}
.btn{max-width:100%}
@media(max-width:560px){
  .btn, .btn-lg{white-space:normal;text-align:center;line-height:1.25}
  .btn-lg{padding:.95em 1.35em;font-size:1rem}
}
/* reveal is position-only so content is ALWAYS visible even if a CMS editor
   (e.g. the Nifty live editor) pauses or strips CSS animations */
.rv, .rv2, .rv3{opacity:1}
.rv{animation:rvIn .8s both}
.rv2{animation:rvIn .8s .12s both}
.rv3{animation:rvIn .8s .24s both}
@keyframes rvIn{from{transform:translateY(22px)}to{transform:none}}
@media (prefers-reduced-motion:reduce){
  .rv, .rv2, .rv3{animation:none!important}
  html{scroll-behavior:auto}
}
.util .wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:8px;padding-bottom:8px}
.hdr .wrap{position:relative;max-width:1420px}
.mega-foot .btn{padding:.6em 1.1em;font-size:.86rem}
@media(max-width:1320px){
  .nav-mcta .btn{width:100%;justify-content:center}
}
.hero .wrap{padding-top:clamp(46px,7vw,88px);padding-bottom:clamp(56px,8vw,104px)}
.hero h1 .g{background:linear-gradient(100deg,#ffe08a,#ffb23a 40%,#f7a80a 70%,#ffd874);-webkit-background-clip:text;background-clip:text;color:transparent;
  background-size:220% auto;animation:sheen 6s linear infinite;filter:drop-shadow(0 0 24px rgba(247,168,10,.45))}
@keyframes sheen{to{background-position:220% center}}
/* ---------- section shells ---------- */
.sec{padding:clamp(58px,8vw,104px) 0;position:relative}
/* Every dark section paints its own background so it does NOT depend on the
   page body (a CMS like Nifty renders on its own light canvas). Light 'rowlight'
   rows are excluded and keep their light background. background-color only, so
   sections with their own gradient (.proc/.quote) keep it layered on top. */
.sec:not(.rowlight){background-color:var(--bg)}
main{background-color:var(--bg)}
.sec-head{max-width:660px;margin:0 auto clamp(34px,5vw,52px);text-align:center}
.sec-head.left{margin-left:0;text-align:left}
.sec-head h2{font-size:clamp(1.85rem,3.6vw,2.9rem);margin:12px 0 0}
.sec-head p{color:var(--mut);font-size:1.08rem;margin:14px 0 0}
.vc{background:var(--glass);border:1px solid var(--line);border-radius:var(--r);padding:28px;
  transition:transform .2s,box-shadow .2s,border-color .2s;position:relative;overflow:hidden;backdrop-filter:blur(12px)}
.vc:hover{transform:translateY(-6px);box-shadow:var(--glow);border-color:var(--line2)}
.vc::before{content:"";position:absolute;inset:0 0 auto 0;height:3px}
.vc.a::before{background:linear-gradient(90deg,var(--cyan),transparent)}
.vc.b::before{background:linear-gradient(90deg,var(--violet),transparent)}
.vc.c::before{background:linear-gradient(90deg,var(--blue),transparent)}
.vc-ic{width:56px;height:56px;border-radius:15px;display:flex;align-items:center;justify-content:center;margin-bottom:16px;border:1px solid var(--line2)}
.vc.a .vc-ic{background:rgba(247,168,10,.12)}
.vc.a .vc-ic svg{color:var(--cyan)}
.vc.b .vc-ic{background:rgba(247,168,10,.14)}
.vc.b .vc-ic svg{color:var(--violet)}
.vc.c .vc-ic{background:rgba(59,130,246,.14)}
.vc.c .vc-ic svg{color:#7ab0ff}
.vc-ic svg{width:28px;height:28px}
.vc h3{font-size:1.3rem}
.vc p{color:var(--ink2);margin:10px 0 0;font-size:.98rem}
.vc .num{position:absolute;right:18px;top:12px;font-family:var(--fdisp);font-weight:800;
  font-size:2.6rem;color:rgba(255,255,255,.05);z-index:0}
.seo-val .n{flex:0 0 auto;font-family:var(--fdisp);font-weight:800;font-size:3rem;background:linear-gradient(100deg,#ffe08a,#f7a80a);-webkit-background-clip:text;background-clip:text;color:transparent;line-height:1;filter:drop-shadow(0 0 18px rgba(247,168,10,.5))}
@media (prefers-reduced-motion:no-preference){
  .seo-val .n{transform-origin:center;animation:pricePulse 2.4s ease-in-out infinite;will-change:transform}
  @keyframes pricePulse{0%,100%{transform:scale(1);filter:drop-shadow(0 0 14px rgba(247,168,10,.35))}
    50%{transform:scale(1.07);filter:drop-shadow(0 0 26px rgba(247,168,10,.7))}}
}
.rev{background:var(--glass);border:1px solid var(--line);border-radius:var(--r);padding:24px;
  display:flex;flex-direction:column;transition:transform .2s,box-shadow .2s,border-color .2s;backdrop-filter:blur(12px)}
.rev:hover{transform:translateY(-5px);box-shadow:var(--glow);border-color:var(--line2)}
.rev .star{color:var(--cyan);letter-spacing:2px;font-size:1.05rem;filter:drop-shadow(0 0 8px rgba(247,168,10,.5))}
.rev p{font-size:.98rem;margin:12px 0 16px;color:var(--ink2)}
.rev .who{margin-top:auto;display:flex;align-items:center;gap:11px}
.rev .av{width:42px;height:42px;border-radius:50%;background:linear-gradient(135deg,#f7a80a,#f7a80a);
  display:flex;align-items:center;justify-content:center;font-family:var(--fdisp);font-weight:800;color:#04121a;flex-shrink:0;box-shadow:0 0 18px -6px var(--gcyan)}
.rev .who b{font-family:var(--fdisp);font-size:.94rem;display:block}
.rev .who span{font-size:.82rem;color:var(--mut)}
.plan .btn{margin-top:auto;width:100%;justify-content:center}
.care-card .btn{margin-top:auto;width:100%;justify-content:center;margin-top:20px}
.qnav .btn{font-size:.92rem}
#pricing .phow-step .n{position:absolute;left:18px;top:18px;width:32px;height:32px;border-radius:10px;background:var(--grad);color:#161616;font-family:var(--fdisp);font-weight:800;font-size:1rem;display:flex;align-items:center;justify-content:center}
#pricing .plan-cta .btn{margin-top:0;flex:1 1 0;min-width:0;width:auto;justify-content:center;font-size:.92rem;padding-left:.8em;padding-right:.8em}

/* ===== Muscle Up case study — scoped (mu-*) ===== */
.mu-band{position:relative;overflow:hidden;padding:clamp(56px,8vw,104px) 0 clamp(40px,6vw,72px);color:#eaf0f8;
  background:radial-gradient(1100px 560px at 82% -10%,rgba(247,168,10,.26),transparent 60%),
             radial-gradient(900px 520px at 4% 8%,rgba(59,130,246,.20),transparent 58%),
             linear-gradient(180deg,#0c1122,#070a14)}
.mu-band::before{content:"";position:absolute;inset:0;opacity:.5;pointer-events:none;
  background-image:linear-gradient(rgba(120,150,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(120,150,255,.06) 1px,transparent 1px);
  background-size:56px 56px;-webkit-mask-image:radial-gradient(1000px 620px at 50% 12%,#000,transparent 80%);mask-image:radial-gradient(1000px 620px at 50% 12%,#000,transparent 80%)}
.mu-band::after{content:"";position:absolute;left:0;right:0;bottom:0;height:110px;pointer-events:none;background:linear-gradient(180deg,transparent,var(--bg))}
.mu-band .wrap{position:relative;z-index:1}
/* image slots, identical to the standard portfolio template */
.ph-img{display:block;width:100%;height:auto;border-radius:16px}
.ph-img.showcase{max-width:1000px;margin:0 auto}
.mu-prose{max-width:820px;margin:0 auto}
.mu-prose p{color:var(--ink2);font-size:1.08rem;line-height:1.7;margin:0 0 18px}
.mu-prose p strong{color:var(--ink)}
.mu-split{display:grid;grid-template-columns:1fr 1fr;gap:clamp(28px,4vw,56px);align-items:center}
.mu-split.rev .mu-split-media{order:2}
.mu-split-body h2{font-size:clamp(1.6rem,3.2vw,2.4rem);margin:0 0 14px}
.mu-split-body p{color:var(--ink2);font-size:1.05rem;line-height:1.65;margin:0 0 16px}
@media(max-width:880px){.mu-split{grid-template-columns:1fr}.mu-split.rev .mu-split-media{order:0}}
.mu-flow{display:flex;flex-wrap:wrap;align-items:stretch;gap:12px;margin:22px 0 4px}
.mu-flow-step{flex:1 1 0;min-width:120px;background:var(--glass);border:1px solid var(--line2);border-radius:14px;padding:16px 14px;text-align:center;backdrop-filter:blur(10px)}
.mu-flow-step .n{display:inline-flex;width:30px;height:30px;border-radius:9px;align-items:center;justify-content:center;font-family:var(--fdisp);font-weight:800;color:#231704;background:linear-gradient(135deg,#ffc247,#f7a80a);margin-bottom:9px}
.mu-flow-step b{display:block;font-family:var(--fdisp);font-size:.95rem;color:var(--ink)}
.mu-flow-step small{color:var(--mut);font-size:.78rem}
.mu-flow-arrow{display:flex;align-items:center;color:#f7a80a;flex:0 0 auto}
.mu-flow-arrow svg{width:22px;height:22px}
@media(max-width:620px){.mu-flow{flex-direction:column}.mu-flow-arrow{transform:rotate(90deg);align-self:center}}
.mu-cards3{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:8px}
.mu-card{background:var(--glass);border:1px solid var(--line2);border-radius:16px;padding:26px;backdrop-filter:blur(10px)}
.mu-card .mu-ic{width:48px;height:48px;border-radius:13px;display:flex;align-items:center;justify-content:center;background:rgba(247,168,10,.12);border:1px solid rgba(247,168,10,.3);margin-bottom:14px}
.mu-card .mu-ic svg{width:24px;height:24px;stroke:#f7a80a}
.mu-card h4{font-family:var(--fdisp);font-size:1.1rem;margin:0 0 8px}
.mu-card p{color:var(--ink2);font-size:.96rem;line-height:1.55;margin:0}
@media(max-width:820px){.mu-cards3{grid-template-columns:1fr}}
.mu-feat{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.mu-feat .vc{padding:24px}
.mu-feat .vc h3{font-size:1.05rem;margin:0 0 6px}
.mu-feat .vc p{margin:0}
@media(max-width:960px){.mu-feat{grid-template-columns:repeat(2,1fr)}}
@media(max-width:620px){.mu-feat{grid-template-columns:1fr}}
.mu-journey{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;align-items:center;margin-top:8px}
.mu-journey .j{background:linear-gradient(180deg,rgba(247,168,10,.12),rgba(247,168,10,.04));border:1px solid rgba(247,168,10,.32);
  color:var(--ink);font-family:var(--fdisp);font-weight:700;font-size:.9rem;padding:.65em 1em;border-radius:12px}
.mu-journey .a{color:#f7a80a;font-weight:800}
.mu-hl{background:linear-gradient(155deg,rgba(247,168,10,.14),rgba(247,168,10,.04));border:1px solid rgba(247,168,10,.4);border-radius:22px;padding:clamp(28px,4vw,48px);text-align:center;max-width:960px;margin:0 auto}
.mu-hl .eyebrow{color:var(--amber)}
.mu-hl h2{font-size:clamp(1.6rem,3.2vw,2.4rem);margin:8px 0 14px}
.mu-hl p{color:var(--ink2);font-size:1.06rem;line-height:1.65;max-width:800px;margin:0 auto}
/* light hero (matches standard portfolio hero) */
.mu2-hero{position:relative;overflow:hidden;color:#141821;background:#ffffff;
  background-image:radial-gradient(760px 380px at 88% -14%,rgba(247,168,10,.14),transparent 60%),radial-gradient(620px 320px at 4% 8%,rgba(59,130,246,.07),transparent 58%);border-bottom:1px solid #ececf1}
.mu2-hero .wrap{position:relative;z-index:1;padding-top:clamp(26px,4vw,44px);padding-bottom:clamp(44px,6vw,74px)}
.mu2-crumb{font-size:.86rem;display:flex;gap:8px;flex-wrap:wrap;align-items:center;color:#6b7180}
.mu2-crumb a{color:#6b7180;text-decoration:none}.mu2-crumb a:hover{color:#d07f00}.mu2-crumb .sep{opacity:.5}
.mu2-in{display:grid;grid-template-columns:1.15fr .85fr;gap:clamp(26px,4vw,54px);align-items:center;margin-top:22px}
.mu2-eye{display:inline-flex;align-items:center;gap:9px;padding:7px 14px;border-radius:999px;background:#fff5e3;border:1px solid #f2d295;font-family:var(--fdisp);font-weight:700;font-size:.76rem;letter-spacing:.13em;text-transform:uppercase;color:#b0740a}
.mu2-hero h1{font-family:var(--fdisp);font-weight:800;font-size:clamp(2rem,4.2vw,3.1rem);margin:18px 0 0;line-height:1.08;letter-spacing:-.02em;color:#141821}
.mu2-hero h1 .g{background:linear-gradient(100deg,#eaa100,#d07f00);-webkit-background-clip:text;background-clip:text;color:transparent}
.mu2-answer{font-size:clamp(1.05rem,1.6vw,1.2rem);color:#4b5261;margin:20px 0 0;max-width:62ch;line-height:1.6}
.mu2-cta{display:flex;flex-wrap:wrap;gap:13px;margin:28px 0 0}
.mu2-hero .btn-ghost{background:#ffffff;color:#141821;border:1px solid #d9dce3;backdrop-filter:none}
.mu2-hero .btn-ghost:hover{border-color:var(--amber);box-shadow:0 8px 22px -10px rgba(20,24,33,.28)}
.mu2-meta{display:flex;flex-wrap:wrap;margin:26px 0 0;border:1px solid #e7e9ef;border-radius:14px;overflow:hidden;background:#fbfbfd;max-width:660px}
.mu2-pm{display:flex;flex-direction:column;gap:4px;padding:14px 20px;flex:1 1 150px;min-width:0;border-right:1px solid #e7e9ef}
.mu2-pm:last-child{border-right:0}
.mu2-pm-l{font-family:var(--fdisp);font-size:.66rem;letter-spacing:.1em;text-transform:uppercase;color:#8a8f9c;display:inline-flex;align-items:center;gap:6px}
.mu2-pm-l svg{width:13px;height:13px;color:var(--amber);flex:none}
.mu2-pm-v{font-family:var(--fdisp);font-weight:700;font-size:.98rem;color:#1a1e28;line-height:1.25}
.mu2-media{position:relative}

@media(max-width:900px){.mu2-in{grid-template-columns:1fr}.mu2-answer{max-width:none}}
@media(max-width:560px){.mu2-meta{flex-direction:column}.mu2-pm{border-right:0;border-bottom:1px solid #e7e9ef}.mu2-pm:last-child{border-bottom:0}}

@import url("https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700;800&family=Inter:wght@400;500;600;700&display=swap");

/* ===== base styles carried over from the site stylesheet ===== */
ul, ol{list-style:revert;margin:revert;padding:revert}
li{list-style:revert}
img, svg, video{max-width:revert;height:revert;display:revert;vertical-align:revert}
button, input, select, textarea{font:revert;color:revert;background:revert;border:revert;margin:revert;padding:revert;text-align:revert;line-height:revert}
table{border-collapse:revert;text-indent:revert}
blockquote, figure, fieldset{margin:revert;padding:revert}
h1, h2, h3, h4, h5, h6{font-size:revert;font-weight:revert;margin:revert;line-height:revert}
p{margin:revert}
a{color:revert;text-decoration:revert}
hr{border:revert;height:revert;color:revert}

*{box-sizing:border-box}
:root{/* static accents — same in both themes. Main = yellow; blue = the one 'touch' accent */
  --amber:#f7a80a;--amber-l:#ffc247;--gold:#ffd874;--amber-d:#c47a08;
  --cyan:#f7a80a;--cyan-d:#c47a08;--violet:#f7a80a;--violet-d:#c47a08;
  --blue:#3b82f6;--blue-l:#7ab0ff;--pink:#f7a80a;--green:#34e0a1;
  --grad:linear-gradient(120deg,#ffd874,#f7a80a);
  --grad-b:linear-gradient(120deg,#7ab0ff,#3b82f6);
  --gcyan:rgba(247,168,10,.55);--gviolet:rgba(247,168,10,.42);
  --gut:clamp(18px,5vw,44px);
  --fdisp:'Sora',system-ui,sans-serif;--fbody:'Inter',system-ui,sans-serif;
  --r:18px;}
/* ---- dark theme (default) — swappable tokens live on .site ---- */
:root{--bg:#07080f;--bg2:#0b0d16;--bg3:#0e1018;
  --ink:#f4f6fb;--ink2:#c9cfdd;--mut:#8b93a8;
  --line:rgba(255,255,255,.10);--line2:rgba(255,255,255,.18);
  --glass:rgba(255,255,255,.045);--glass2:rgba(255,255,255,.08);
  --base:#0a0c15;--cream:#0c0e18;
  --hdrbg:#0a0d16;--hdrtext:#dbe2f5;--capbg:#0c0f1c;--menubg:#0d111d;
  --utilbg:#05060f;--utiltext:#9aa3c0;
  --shadow:0 24px 60px -28px rgba(0,0,0,.8);
  --glow:0 0 0 1px rgba(247,168,10,.3),0 18px 50px -18px rgba(247,168,10,.3),0 10px 40px -14px rgba(0,0,0,.5);
  --page-grad:radial-gradient(900px 600px at 12% -5%,rgba(247,168,10,.10),transparent 60%),radial-gradient(900px 620px at 92% 4%,rgba(59,130,246,.10),transparent 60%)}
/* ---- WHITE rows — light section to break up the dark ---- */
.rowlight{background:#f4f6fc;
  --ink:#0e1424;--ink2:#42506a;--mut:#697390;
  --line:rgba(14,20,36,.10);--line2:rgba(14,20,36,.16);
  --glass:#ffffff;--glass2:#eef2f9;
  --base:#f4f6fc;--cream:#f4f6fc;
  --glow:0 0 0 1px rgba(247,168,10,.35),0 18px 40px -20px rgba(247,168,10,.3),0 10px 30px -16px rgba(20,30,60,.15);
  color:var(--ink)}
.rowlight .vc, .rowlight .svc, .rowlight .rev, .rowlight .plan, .rowlight .ind, .rowlight .pstep{box-shadow:0 14px 36px -22px rgba(20,30,60,.3)}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);background-image:var(--page-grad);background-attachment:fixed;
  color:var(--ink);min-height:100vh;font-family:var(--fbody);
  font-size:16.5px;line-height:1.62;-webkit-font-smoothing:antialiased;overflow-x:hidden}
img{max-width:100%;display:block}
svg{width:18px;height:18px;flex-shrink:0}
a{color:inherit;text-decoration:none}
h1, h2, h3, h4{font-family:var(--fdisp);line-height:1.06;margin:0;letter-spacing:-.02em;font-weight:800}
p{margin:0 0 1em}
.wrap{max-width:1240px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.eyebrow{font-family:var(--fdisp);font-weight:700;font-size:.78rem;letter-spacing:.18em;
  text-transform:uppercase;color:var(--cyan)}
.k-amber{background:linear-gradient(100deg,#ffd874,#ffb23a 50%,#f7a80a);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 16px rgba(247,168,10,.35))}
.btn{display:inline-flex;align-items:center;gap:.5em;font-family:var(--fdisp);font-weight:700;
  font-size:.98rem;padding:.85em 1.5em;border-radius:999px;border:0;cursor:pointer;
  transition:transform .18s,box-shadow .18s,background .18s,border-color .18s;white-space:nowrap;position:relative}
.btn svg{width:18px;height:18px}
.btn-amber{background:linear-gradient(135deg,#ffc247,#f7a80a);color:#231704;
  box-shadow:0 0 26px -4px rgba(247,168,10,.6),0 0 46px -12px rgba(247,168,10,.45)}
.btn-amber:hover{transform:translateY(-3px);box-shadow:0 0 36px -2px rgba(247,168,10,.8),0 0 60px -10px rgba(247,168,10,.5)}
.btn-ghost{background:var(--glass);color:#fff;border:1px solid var(--line2);backdrop-filter:blur(8px)}
.btn-ghost:hover{border-color:var(--cyan);transform:translateY(-3px);box-shadow:0 0 24px -6px var(--gcyan)}
.btn-lg{padding:1.05em 1.9em;font-size:1.05rem}
.btn{max-width:100%}
@media(max-width:560px){
  .btn, .btn-lg{white-space:normal;text-align:center;line-height:1.25}
  .btn-lg{padding:.95em 1.35em;font-size:1rem}
}
/* reveal is position-only so content is ALWAYS visible even if a CMS editor
   (e.g. the Nifty live editor) pauses or strips CSS animations */
.rv, .rv2, .rv3{opacity:1}
.rv{animation:rvIn .8s both}
.rv2{animation:rvIn .8s .12s both}
.rv3{animation:rvIn .8s .24s both}
@keyframes rvIn{from{transform:translateY(22px)}to{transform:none}}
@media (prefers-reduced-motion:reduce){
  .rv, .rv2, .rv3{animation:none!important}
  html{scroll-behavior:auto}
}
.util .wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:8px;padding-bottom:8px}
